# %% [markdown]
# # Timeless Compass: GPU render shard
# Renders ONE shard of a job's shots on Kaggle's free GPU (T4 / P100), then joins each finished shot into a video.
# Generated by `python -m tc kaggle <job> --shard N`, which fills in JOB and INDEX below.
# Kaggle settings it needs: Accelerator = GPU, Internet = On (both set by kernel-metadata.json).
# Safe to run again: finished shots are skipped (progress.json), and a new session can resume the last one's output.

# %%
# ---- 0. settings (filled in by the generator) -------------------------------------------------------------------
JOB = "{{JOB}}"                  # the job id; its bundle is cloud/bundles/<JOB>.json in the repo
WHERE = "kaggle"
INDEX = {{INDEX}}                # which kaggle shard of the render plan this session renders
REPO = "{{REPO}}"                # public repo: no secrets in it, nothing secret needed to clone it
BRANCH = "{{BRANCH}}"
BUDGET_H = {{BUDGET_H}}          # stop STARTING new shots after this many hours (Kaggle ends sessions at 12 h)
R2_PUBLIC_URL = "{{R2_PUBLIC_URL}}"   # optional public read URL of the R2 asset cache ('' = use Poly Haven fallback)

import glob, json, os, shutil, subprocess, sys
WORK = "/kaggle/working"         # saved as the notebook's output when the session ends
SHARD = f"{WORK}/{WHERE}-{INDEX}"  # frames, videos, progress.json, logs of this shard (kaggle-0, kaggle-1, ...)
CODE = "/kaggle/tmp/tc"          # the repo; /kaggle/tmp is NOT saved, so the output stays small
TOOLS = "/kaggle/tmp/tools"      # Blender + MPFB (~1 GB, not saved either)
os.makedirs(SHARD, exist_ok=True)

def sh(cmd, **kw):
    """Run a shell command, show it, stop the notebook if it fails."""
    print("$", cmd if isinstance(cmd, str) else " ".join(cmd), flush=True)
    return subprocess.run(cmd, shell=isinstance(cmd, str), check=True, **kw)

# %%
# ---- 1. is there a GPU? -----------------------------------------------------------------------------------------
sh("nvidia-smi --query-gpu=name,memory.total --format=csv")

# %%
# ---- 2. the code (shallow clone of one branch) ------------------------------------------------------------------
if not os.path.isdir(CODE):
    sh(["git", "clone", "--depth", "1", "-b", BRANCH, REPO, CODE])
os.chdir(CODE)
BUNDLE = f"{CODE}/cloud/bundles/{JOB}.json"
assert os.path.exists(BUNDLE), f"{BUNDLE} missing: on the laptop run  tc render-bundle {JOB}  and push it"
sh([sys.executable, "-m", "pip", "install", "-q", "numpy", "pillow"])

# %%
# ---- 3. Blender 5.3 + MPFB (MakeHuman) extension + its CC0 assets ------------------------------------------------
BLENDER = subprocess.run(["bash", "cloud/setup_blender_linux.sh", TOOLS], capture_output=True, text=True,
                         check=True).stdout.strip().splitlines()[-1]
print("blender:", BLENDER)
# Eevee needs an OpenGL context. Headless Kaggle normally gives one through EGL; if not, wide shots fall back to
# Cycles (slower, still correct) instead of failing.
eevee = subprocess.run([BLENDER, "-b", "--python-expr",
    "import bpy; s=bpy.context.scene; names=[e.identifier for e in bpy.types.RenderSettings.bl_rna.properties['engine'].enum_items];"
    "s.render.engine='BLENDER_EEVEE' if 'BLENDER_EEVEE' in names else 'BLENDER_EEVEE_NEXT';"
    "s.render.resolution_x=s.render.resolution_y=64; s.render.filepath='/kaggle/tmp/eevee.png'; bpy.ops.render.render(write_still=True)"],
    capture_output=True, text=True)
if eevee.returncode != 0 or not os.path.exists("/kaggle/tmp/eevee.png"):
    os.environ["TC_FORCE_CYCLES"] = "1"
    print("Eevee not available here -> wide shots render in Cycles")

# %%
# ---- 4. resume: copy the previous session's output (attached as input by the generator) ------------------------
for prev in glob.glob(f"/kaggle/input/*/{WHERE}-{INDEX}"):
    print("resuming from", prev)
    shutil.copytree(prev, SHARD, dirs_exist_ok=True)   # progress.json + finished videos + half-done frames

# %%
# ---- 5. only the scans THIS shard needs (R2 cache, or Poly Haven for free) -------------------------------------
if R2_PUBLIC_URL:
    os.environ["TC_R2_PUBLIC_URL"] = R2_PUBLIC_URL
os.environ["TC_SCANS_CAP_GB"] = "15"                   # Kaggle has ~70 GB of scratch disk
sh([sys.executable, "-m", "tc", "cache", "fetch", "--bundle", BUNDLE, "--shard", f"{WHERE}:{INDEX}"])

# %%
# ---- 6. render (GPU: OptiX/CUDA chosen inside Blender because TC_GPU=1) -----------------------------------------
r = subprocess.run([sys.executable, "-m", "tc", "render-shard", BUNDLE, "--where", WHERE, "--index", str(INDEX),
                    "--out", SHARD, "--blender", BLENDER, "--budget-h", str(BUDGET_H), "--join"])
print("render-shard exit code", r.returncode, "(1 = some shots failed, see progress.json)")

# %%
# ---- 7. tidy + summary: keep videos, progress and logs; drop the frames of shots that are joined ----------------
prog = json.load(open(f"{SHARD}/progress.json")) if os.path.exists(f"{SHARD}/progress.json") else {}
for sid, e in prog.items():
    if e.get("status") == "done" and os.path.exists(f"{SHARD}/{sid}.mp4"):
        shutil.rmtree(f"{SHARD}/{sid}/frames", ignore_errors=True)
counts = {}
for e in prog.values():
    counts[e["status"]] = counts.get(e["status"], 0) + 1
print("shots by status:", counts)
print(f"Output tab -> {WHERE}-{INDEX}/ (videos + progress.json). Not done? Run  tc kaggle", JOB, "--shard", INDEX,
      "--resume  on the laptop to continue in a new session.")
